textos = {k: io.open(v, encoding="utf-8", newline="").read()
          for k, v in ARCHIVOS.items()}
saltados = []


def cambiar(clave, viejo, nuevo, marca=None):
    t = textos[clave]
    if (marca or nuevo) in t:
        saltados.append(clave)
        return
    assert t.count(viejo) == 1, (
        f"{clave}: '{viejo[:70]}...' esta {t.count(viejo)} veces. "
        "No se escribio nada.")
    textos[clave] = t.replace(viejo, nuevo)


cambiar('bonos',
        '  - grave:       la gestiona Recursos Humanos, quita todas las estrellas\n"""\nimport calendar\nfrom datetime import date, timedelta\nfrom decimal import Decimal\n\nfrom fastapi import HTTPException\n',
        '  - grave:       la gestiona Recursos Humanos, quita todas las estrellas\n"""\nimport calendar\nfrom datetime import date, datetime, time, timedelta\nfrom decimal import Decimal\n\nfrom fastapi import HTTPException\n')

